 float *m=0,*s=0;WL_U64 n=0;WL_U32 rate=0;static const WL_WCHAR path[]={'x',0};unsigned char wav[]={ 'R','I','F','F',40,0,0,0,'W','A','V','E','f','m','t',' ',16,0,0,0,1,0,2,0,128,187,0,0,0,238,2,0,4,0,16,0,'d','a','t','a',4,0,0,0,0,64,0,224};memcpy(disk,wav,sizeof(wav));len=sizeof(wav);check(decode_wav(path,&m,&s,&n,&rate,0)&&n==1&&rate==48000&&fabs(m[0]-.125)<1e-6&&fabs(s[0]-.375)<1e-6,"Stereo PCM decode");free(m);free(s);memset(disk+40,255,4);check(!decode_wav(path,&m,&s,&n,&rate,0),"Reject overflowing WAV chunk size");
